const decode=(s:string)=>s.replace(/&quot;/g,'"').replace(/&#x27;/g,"'").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&amp;/g,"&");
const attrs=(s:string)=>Object.fromEntries([...s.matchAll(/([\w:-]+)="([^"]*)"/g)].map(m=>[m[1],decode(m[2])]));
const tags=(svg:string,tag:string)=>[...svg.matchAll(new RegExp(`<${tag}\\b([^>]*)>`,"g"))].map(m=>attrs(m[1]));
const points=(a:Record<string,string>,keys:readonly string[])=>keys.map(k=>{assert(k in a);assert(Number.isFinite(Number(a[k])));return Number(a[k]);});
const rectKeys=["x","y","width","height"],lineKeys=["x1","y1","x2","y2"];
const group=(svg:string,key:string,value:string)=>{const escaped=value.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"),m=svg.match(new RegExp(`<g ${key}="${escaped}">([\\s\\S]*?)<\\/g>`));assert(m,`${key}=${value}`);return m[1];};
const texts=(svg:string)=>[...svg.matchAll(/<text\b([^>]*)>([^<]*)<\/text>/g)].map(m=>({attrs:attrs(m[1]),text:decode(m[2])}));
function marker(svg:string){const m=svg.match(/<marker\b([^>]*)>([\s\S]*?)<\/marker>/);assert(m);assert.equal(tags(svg,"marker").length,1);const a=attrs(m[1]);assert.deepEqual({...a,id:"reviewed-id"},{id:"reviewed-id",viewBox:"0 0 10 10",refX:"9",refY:"5",markerWidth:"7",markerHeight:"7",orient:"auto"});assert.deepEqual(tags(m[2],"path"),[{d:"M 1 1 L 9 5 L 1 9",fill:"none",stroke:"currentColor","stroke-width":"1.5"}]);return a.id;}
function labelledTextMap(svg:string,key="data-label"){return new Map(texts(svg).filter(t=>key in t.attrs).map(t=>[t.attrs[key],t]));}
export function systemsSvg(profile:string,values:number[]){return renderToStaticMarkup(createElement(Legacy2017SystemsFigure,{profile,values,caption:"年度図の独立検査"}));}
