 const id=marker(svg);const descriptions=[...svg.matchAll(/<desc id="([^"]+)">([^<]+)<\/desc>/g)];assert.equal(descriptions.length,1);assert(svg.includes(`aria-describedby="${descriptions[0][1]}"`));assert.equal(decode(descriptions[0][2]),systemsFigureText(profile,values).description);assert.doesNotMatch(svg,/\bopacity="0"|\bvisibility="hidden"|\bdisplay="none"/);
