  for(const [name,geometry]of Object.entries(halfGeometry.gates))assert.deepEqual(points(tags(group(svg,"data-gate",name),"rect")[0],rectKeys),geometry);
  for(const [name,d]of Object.entries(halfGeometry.paths)){const p=tags(svg,"path").find(a=>a["data-wire"]===name);assert(p);assert.equal(p.d,d);}
