 assert.equal(profile,"legacy-2017-ftth-home-network");assert.match(svg,/viewBox="0 0 1300 290"/);assert.equal(tags(svg,"rect").length,6);assert.equal(tags(svg,"line").length,5);assert.equal(tags(svg,"text").length,8);assert.equal(tags(svg,"path").length,1);
 assert.deepEqual(points(tags(svg,"rect").find(a=>a["data-home-boundary"]==="true")!,rectKeys),homeGeometry.boundary);for(const [name,p]of Object.entries(homeGeometry.nodes))assert.deepEqual(points(tags(group(svg,"data-network-node",name),"rect")[0],rectKeys),p);for(const [name,p]of Object.entries(homeGeometry.wires)){const a=tags(svg,"line").find(a=>a["data-wire"]===name)!;assert(a);assert.deepEqual(points(a,lineKeys),p);}const labels=labelledTextMap(svg);for(const [name,p]of Object.entries(homeGeometry.labels)){const t=labels.get(name)!;assert(t);assert.deepEqual([...points(t.attrs,["x","y"]),t.text],p);}return {kind:"home"as const,chain:["PC1/PC2","hub","A","ONU","FTTH"]};
