/** Attribute closure and a union-find chase are independent of producer graphs. */
export function systemsFdClosure(seed:Iterable<string>,edges:readonly string[]){const out=new Set(seed);let changed=true;while(changed){changed=false;for(const e of edges){const [a,b]=e.split(">");if(out.has(a)&&!out.has(b)){out.add(b);changed=true;}}}return out;}
export function systemsLossless(tables:readonly string[],edges:readonly string[]){
 const letters="abcdefghij".split(""),rows=tables.map((t,r)=>letters.map(c=>t.includes(c)?`a${c}`:`b${r}${c}`)),parent=new Map<string,string>();const root=(s:string):string=>{const p=parent.get(s);if(!p)return s;const r=root(p);parent.set(s,r);return r;};const union=(x:string,y:string)=>{const a=root(x),b=root(y);if(a===b)return false;const first=a.startsWith("a")?a:b.startsWith("a")?b:a;parent.set(first===a?b:a,first);return true;};let changed=true;while(changed){changed=false;for(const edge of edges){const [a,b]=edge.split(">").map(c=>letters.indexOf(c));for(let r=0;r<rows.length;r++)for(let s=r+1;s<rows.length;s++)if(root(rows[r][a])===root(rows[s][a]))changed=union(rows[r][b],rows[s][b])||changed;}}return rows.some(row=>row.every((s,i)=>root(s)===root(`a${letters[i]}`)));
}
export function systemsBcnf(table:string,edges:readonly string[]){const letters=table.split("");for(let bits=1;bits<2**letters.length;bits++){const seed=letters.filter((_,i)=>bits&(1<<i)),closure=systemsFdClosure(seed,edges),projected=letters.filter(c=>closure.has(c));if(projected.some(c=>!seed.includes(c))&&projected.length!==letters.length)return false;}return true;}
export function systemsFdPreserved(tables:readonly string[],edges:readonly string[]){const projected:string[]=[];for(const t of tables)for(const a of t)for(const b of t)if(a!==b&&systemsFdClosure([a],edges).has(b))projected.push(`${a}>${b}`);return edges.every(e=>{const [a,b]=e.split(">");return systemsFdClosure([a],projected).has(b);});}
export function systemsMultiplicationRow(width:number,initialShift:number,row:string[]){const scan=Number(row[0].match(/^Yの第(\d+)ビット$/)?.[1]),match=row[1].match(/^Xを1ビット(左|右)シフト、Yを1ビット(左|右)シフト$/);assert(match&&Number.isInteger(scan));const dx=match[1]==="左"?1:-1,dy=match[2]==="右"?1:-1;const positions=[];for(let i=0;i<width;i++){const bit=scan+dy*i,weight=initialShift+dx*i;if(bit<0||bit>=width||weight!==bit)return false;positions.push(bit);}return new Set(positions).size===width;}
export function systemsMultiplyTrace(width:number,initialShift:number,row:string[],multiplicand:number,multiplier:number){let x=multiplicand*2**initialShift,y=multiplier,z=0;const limit=2**(2*width),scan=Number(row[0].match(/第(\d+)ビット/)![1]),match=row[1].match(/^Xを1ビット(左|右)シフト、Yを1ビット(左|右)シフト$/)!;for(let i=0;i<width;i++){if(Math.floor(y/2**scan)%2)z=(z+x)%limit;x=match[1]==="左"?(x*2)%limit:Math.floor(x/2);y=match[2]==="左"?(y*2)%limit:Math.floor(y/2);}return z;}
export function systemsLedgerAnswer(accounts:string[][],movements:string[][],target:string){const code=accounts.find(r=>r[1]===target)?.[0];assert(code);const blank=movements.find(r=>r[0]==="a"&&r[1]==="b");assert(blank);const amount=Number(blank[2].replace(/,/g,""));assert(Number.isSafeInteger(amount)&&amount>0);const signed=movements.filter(r=>r!==blank&&r[3]===blank[3]).reduce((sum,r)=>{assert(["借方","貸方"].includes(r[1]));return sum+(r[1]==="借方"?1:-1)*Number(r[2].replace(/,/g,""));},0);assert.equal(Math.abs(signed),amount);return [code,signed<0?"借方":"貸方"];}
const paragraph=(b:Block)=>{assert.equal(b.type,"paragraph");if(b.type!=="paragraph")throw Error();return b.text;};
const tableAt=(b:Block)=>{assert.equal(b.type,"table");if(b.type!=="table")throw Error();return b;};
const diagramAt=(b:Block,profile:string,values:number[])=>{assert.equal(b.type,"diagram");if(b.type!=="diagram"||b.scene.kind!=="source_figure")throw Error();assert.equal(b.scene.profile,profile);assert.deepEqual(b.scene.values,values);const expected=systemsFigureText(profile,values);assert.equal(b.caption,expected.caption);assert.equal(b.alt,expected.alt);return readSystemsSvg(profile,systemsSvg(profile,b.scene.values),values);};
